#include <vector>
#include <unordered_map>

using namespace std;

class Solution {
public:
    int countPairs(vector<int>& deliciousness) {
        const int MOD = 1e9 + 7;
        unordered_map<int, int> freq;
        int res = 0;
        for (int x : deliciousness) {
            for (int p = 1; p <= (1 << 21); p <<= 1) {
                res = (res + freq[p - x]) % MOD;
            }
            freq[x]++;
        }
        return res;
    }
};
